import{i as e,o as t,r as n,t as r}from"./app-CKIWtCsy.js";var i=JSON.parse(`{"path":"/%E3%80%90%E6%9B%B8%E7%B1%8D%E3%80%91TheChecklistManifesto.html","title":"【書籍】TheChecklistManifesto","lang":"en-US","frontmatter":{},"git":{},"readingTime":{"minutes":2.49,"words":748},"filePathRelative":"【書籍】TheChecklistManifesto.md"}`),a={name:`【書籍】TheChecklistManifesto.md`};function o(r,i,a,o,s,c){return t(),n(`div`,null,[...i[0]||=[e(`<h1 id="【書籍】thechecklistmanifesto" tabindex="-1"><a class="header-anchor" href="#【書籍】thechecklistmanifesto"><span>【書籍】TheChecklistManifesto</span></a></h1><p><a href="./技術的なメモ.html">技術的なメモ</a>, <a href="./書籍.html">書籍</a></p><p><a href="https://amzn.to/4rhqqO6" target="_blank" rel="noopener noreferrer">amazon: The Checklist Manifesto: How To Get Things Right</a></p><p>チェックリストは凄いんだ、という本。</p><h2 id="購入-2026-02-14-土" tabindex="-1"><a class="header-anchor" href="#購入-2026-02-14-土"><span>購入 2026-02-14 (土)</span></a></h2><p>何かのソフトウェア開発の本で勧められていたのだと思うが、どこで勧められていたかは忘れた。 <a href="./【書籍】患者の話は医師にどう聞こえるのか.html">【書籍】患者の話は医師にどう聞こえるのか</a>でも見かけて、ちょっと興味が出たところ、Kindleにサンプルが入っていた。 へー、という事で読んでみた所、続きを読みたい気分が続いていたのでポチってみた。</p><p>医学の本なので医学用語が多くて病気や器官の単語が分からないなぁ、と思うのだけれど、日本語版は電子化されてないので諦めて英語版を読む。 一応日本語版のリンクを貼っておく。</p><p>日本語版: <a href="https://amzn.to/4qF7IPo" target="_blank" rel="noopener noreferrer">amazon: アナタはなぜチェックリストを使わないのか？</a></p><h2 id="予期しない事態への対応が面白い-2026-02-25-水" tabindex="-1"><a class="header-anchor" href="#予期しない事態への対応が面白い-2026-02-25-水"><span>予期しない事態への対応が面白い 2026-02-25 (水)</span></a></h2><p>この本はICUの医者の著者が航空業界や建築業界のチェックリストの使い方を調べてそれを参考に自身もいろいろ使ってみる、みたいな本。 予想外だったのは、チェックリストでは上手く扱えなさそうな事態が多い所でどう使うかを考える本である、という所。 この上手く扱えなさそうなシチュエーションが「予期できない突発的なトラブル」とかで、 これが多いのは現代の複雑な仕事では一般的という前提に立つ。</p><p>本の結論としては突発的なトラブルには現場に権限を移譲して現場の人間同士で話し合って解決するべき、というもの。 話し合いを確実に行わせるためにチェックリストは有効、という話はするのだけれど。</p><p>この突発的な事態が日常、というのはソフトウェア開発にも通じる部分があるよなぁ。 前回と同じならソフトウェア開発には難しい事が無いのだけれど、いつも何か前回と違う困難が発生して、 しかもそれらはその都度その場特有の何かでその場で解決して前に進む類のものだったりする。 これは報告も難しいし、これが仕事を測ったり管理したりするのを難しくしているな、と以前から思っていた。 だからそういうものが日常的に必ず起こるという前提で考えるのは、親近感を覚える。</p><p>予期せぬ事態にはトップダウンでは無く現場に権力を移譲、分散させたほうがいい、というのは、興味深い話だなぁ、と思った。 ソフトウェア開発でもそういう部分はあるよな。 仕様を決めて外注にやらせる、みたいなのが上手く行かないのは、権力を自分たちが持ったままやらせようとするからで、 それはソフトウェア開発という予期せぬ事態が起こりやすい分野では当然だ、という話にもなりそう。</p><p>権力を現場に移譲したほうがいい、という事の真偽のほどは良く分からないが、自分の経験とは矛盾しない話ではある。</p><h2 id="testまで読んだ、なかなか良い本だ-2026-03-10-火" tabindex="-1"><a class="header-anchor" href="#testまで読んだ、なかなか良い本だ-2026-03-10-火"><span>Testまで読んだ、なかなか良い本だ 2026-03-10 (火)</span></a></h2><p>実際にチェックリストを作る話からそれを広める話くらいまで読んだ。だいたい主要な部分は終わったかな。なかなか良い本だと思う。</p><p>チェックリストを作る話で、最初に失敗する。これがなかなかリアリティを感じて良い。 新しいソフトウェア開発のプラクティスを導入して失敗する話に似ている。</p><p>そこから成功させる為に直した所とか、実際に試して調整する大切さを強調したりするのが好感が持てる。</p><p>効果をテストする為に8箇所の様々な国の医療機関でテストを実施する話や、どういう困難があったのか、という話も、 自分で同じような事をしようと思えばとても参考になる。</p><p>単にチェックリストをこう作れ、というハウツー本としては、無駄な話ばかり、とも言える。 一方で新しい状況に自分で新たにチェックリストを開発して運用していこうと思うのなら、とても役に立つ本に思う。 そして後者の方が現実的には多いのではないか、という気もしてくるな。</p><p>結局皆それぞれ、複雑な仕事をしていて、それぞれの環境に特殊な要因がたくさんある。 だからこうやって新規のチェックリストの作成と運用を各自が「発明」していく必要があるのだろう。</p><h3 id="issue-trackerやprのチェックリストはどうなんだろう" tabindex="-1"><a class="header-anchor" href="#issue-trackerやprのチェックリストはどうなんだろう"><span>Issue TrackerやPRのチェックリストはどうなんだろう？</span></a></h3><p>GitHubなどで、デフォルトのテンプレートとしてチェックリストを提供している所は増えてきていると思う。 これらは多分、本書の影響を受けて作られているものだと思う。 直接読んだ人が作ったか、それとも直接読んで作られたチェックリストをどこかで見てそれを真似したかだろう。</p><p>この手のチェックリストは、有益なものもあれば、形骸化して単に無駄な作業を増やしているだけのものもある。</p><p>本書の失敗例でもあったが、項目を増やしたくなる圧力が働き、そうすると無視したくなり、形骸化する。</p><h2 id="読み終わり-読む価値のある本だった-2026-03-17-火" tabindex="-1"><a class="header-anchor" href="#読み終わり-読む価値のある本だった-2026-03-17-火"><span>読み終わり： 読む価値のある本だった 2026-03-17 (火)</span></a></h2><p>最後まで読んだ。WHOなどにチェックリストを導入した著者が、どのようにしてチェックリストを学び、自分の仕事に適用してみて、 失敗したり成功したりして、それをどうやって広めていこうとしたり広めようとして失敗したりした事を書いた本。 チェックリストを設計しようとしている人が簡単に使えるハウツーというのとは少し違う。 だが、チェックリストというのを現代の複雑な仕事で使おうとするなら、こうした経験を元に自分たちの業界で適用する方法を各自が生み出す必要があると思うし、 そういう視点に立つとまさに必要なのはこういう本だ、という気もする。</p><p>また、読み物としても面白い。最後まで読む気にさせるし、最後まで読むと説得される事も多い。 なんか本を読みたいな、と思っている時に読むのに良い本だと思う。</p><h3 id="無駄なチェックリストが残るリスク" tabindex="-1"><a class="header-anchor" href="#無駄なチェックリストが残るリスク"><span>無駄なチェックリストが残るリスク</span></a></h3><p>本書でも述べられているように、作業を助けるよりもむしろ邪魔になるようなチェックリストが使われ続けるようなシチュエーションはいかにも起きそうで、 これに対する忌避感がソフトウェア開発でチェックリストを導入する時の一番の障害になりそうに思う。 他の業界だとこうしたものの有効性を疑ったり創造的でない感じが嫌われるというのがあると思うが、 ソフトウェア開発の現場ではその辺は割と抵抗無いんじゃないか。</p><p>で、本書では適切にアップデートされ続けないといけない、と言っているだけだが、 実際に適切にアップデートされないで無駄になるというのはすぐに想像出来る。 weeklyのミーティングでもCIでもなんでも、そういったものは枚挙にいとまがない。 だから本当に役に立たないチェックリストが使われ続けるリスクを回避出来るかは興味がわく。</p><p>これは究極的には、一度足した項目を後から消せるか、という話になると思う。 足したものを消すのは意思の力が必要なので出来ない組織もあるよなぁ。</p><p>その辺のリスクを肌で感じるので導入に抵抗があるんだろうな、と思う。 だから抵抗を減らすにはどうやったら不要になった項目を消せるか、というあたりをケアしてやる必要がありそう。</p>`,33)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};